// Comprehensive catalog of 22 After Effects effect categories and all 200+ built-in effects.
// Each effect provides parameter mappings, hints, group, and tags for instant search & FX Console.

import { RENDERED_EFFECTS } from './effectSupport';
export type EffectDefinition = {
  id: string;
  label: string;
  group: EffectCategory;
  hint: string;
  apply: Record<string, number | boolean>;
  tags?: string[];
  isTransition?: boolean;
  isAudio?: boolean;
};

export type EffectCategory =
  | '3D Channel'
  | 'Audio'
  | 'Blur & Sharpen'
  | 'Planar Tracking'
  | 'Channel'
  | 'Color Correction'
  | 'Distort'
  | 'Expression Controls'
  | 'Generate'
  | 'Immersive Video / VR'
  | 'Keying'
  | 'Matte'
  | 'Noise & Grain'
  | 'Perspective'
  | 'Simulation / Particles'
  | 'Stylize'
  | 'Text'
  | 'Time'
  | 'Transition'
  | 'Utility'
  | 'Obsolete / Legacy';

