/** Incomplete legacy entries stay readable in saved projects, but cannot be applied as working effects. */
export const AVAILABLE_EFFECTS = ALL_EFFECTS.filter(effect => RENDERED_EFFECTS.has(effect.id));

/** Quick dictionary of all effects by ID */
export const EFFECT_MAP = new Map<string, EffectDefinition>(ALL_EFFECTS.map((eff) => [eff.id, eff]));

/** Category counts helper */
export const CATEGORY_COUNTS = EFFECT_CATEGORIES.reduce((acc, cat) => {
  acc[cat] = ALL_EFFECTS.filter((eff) => eff.group === cat).length;
  return acc;
}, {} as Record<EffectCategory, number>);
